    private Object activeRegion()throws Exception{return call(editor,"activeRegion");}
    private String selectedRegionId()throws Exception{return (String)get(editor,"selectedRegionId");}
    private List<?> regions()throws Exception{return (List<?>)call(get(editor,"localEdits"),"regions");}
    private List<?> strokes(Object region)throws Exception{return (List<?>)get(region,"strokes");}
    private int maskVisiblePixels(Dialog dialog)throws Exception{int count=0;for(int pixel:(int[])get(dialog,"maskPixels"))if((pixel>>>24)>0)count++;return count;}
    private void verifyCommittedCoverage(Dialog dialog,String label)throws Exception{float[] cached=((float[])get(dialog,"coverage")).clone();Bitmap image=(Bitmap)get(dialog,"initial"),mask=(Bitmap)get(dialog,"mask");Object vector=call(settings(dialog),"compileBrush",new Class<?>[]{int.class,int.class},image.getWidth(),image.getHeight());Method sample=vector.getClass().getMethod("weight",double.class,double.class);sample.setAccessible(true);double error=0;int zeroLeaks=0;for(int y=0;y<mask.getHeight();y++)for(int x=0;x<mask.getWidth();x++){double expected=((Number)sample.invoke(vector,(x+.5)/mask.getWidth(),(y+.5)/mask.getHeight())).doubleValue(),actual=cached[y*mask.getWidth()+x];error=Math.max(error,Math.abs(expected-actual));if(expected==0&&actual!=0)zeroLeaks++;}check("committed-live-cache-matches-vector-"+label,error<=1e-5&&zeroLeaks==0);measurements.put(new JSONObject().put("case","committed-live-coverage-"+label).put("maximumAbsoluteError",error).put("zeroCoverageLeaks",zeroLeaks));}
    private Object regionById(String id)throws Exception{for(Object region:regions())if(id.equals(get(region,"id")))return region;return null;}
    @SuppressWarnings({"rawtypes","unchecked"}) private Object parameter(String name)throws Exception{return Enum.valueOf((Class)type("cc.huevia.ncp.PhotoAdjustments$Parameter"),name);}
    private int parameterValue(Object adjustments,Object parameter)throws Exception{return (Integer)call(adjustments,"get",new Class<?>[]{type("cc.huevia.ncp.PhotoAdjustments$Parameter")},parameter);}
    private Bitmap copyCurrent()throws Exception{waitEditor();Bitmap[] copy={null};ui(()->copy[0]=((Bitmap)get(editor,"current")).copy(Bitmap.Config.ARGB_8888,false));check("actual-final-preview-copied",copy[0]!=null);return copy[0];}
    private View editorTag(String name)throws Exception{View root=(View)get(editor,"dock"),found=root.findViewWithTag(name);if(found==null)throw new AssertionError("Missing real editor control "+name);return found;}
